"use strict";
// Loads its formatter by a computed specifier while the module evaluates:
// the package runs in a Node island.
var util = require(["ut", "il"].join(""));
var factors = { cup: 240, spoon: 15, pinch: 0.5 };
var converters = {};

module.exports = function measure(name, lenient) {
  if (!Object.prototype.hasOwnProperty.call(factors, name)) {
    if (lenient) return undefined;
    throw new RangeError(util.format("no measure named %s", name));
  }
  if (!converters[name]) {
    var factor = factors[name];
    converters[name] = function (amount) {
      return amount * factor;
    };
  }
  return converters[name];
};
